1.remediation:
Ensure instances are launched with appropriate security groups that restrict access. Example:

```hcl
resource "aws_security_group" "project102_sg" {
  name_prefix = "project102-sg"
  vpc_id      = aws_vpc.project102.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

Attach this security group to instances.

3.remediation:
Create a custom route table for public subnets instead of using the default route table. Example:

```hcl
resource "aws_route_table" "public_project102_rt" {
  vpc_id = aws_vpc.project102.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.project102_gw.id
  }

  tags = {
    Name = "public-project102-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = var.public_sn_count
  subnet_id      = aws_subnet.public_project102_subnet[count.index].id
  route_table_id = aws_route_table.public_project102_rt.id
}
```
